img {
  height: 200px;
  width: 200px;
  object-fit: fill | contain | cover | none | scale-down
}

/*
 * Per mostrare soltanto una regione circolare di 60px
 * di diametro posizionata al centro dell'immagine
 */
img {
  clip-path: circle(60px at center);
}

.testo {
  columns: 300px 3; /* crea tre colonne di 300px ciascuna */
  column-gap: 10px; /* crea un gap di 10px tra ogni colonna */
}

.container {
  grid-template-columns:
    auto auto auto auto;
  grid-template-rows:
    100px 250px 150px;
}

.container {
  grid-template-columns:
    [col1] auto
    [col2] auto
    [col3] auto
    [col4] auto [col5];
  grid-template-rows:
    [row1] 100px 
    [row2] 250px 
    [row3] 150px [row4];
}

.container {
  grid-template-columns:
    auto auto auto auto;
  grid-template-rows: 100px 250px 150px;
  grid-template-areas:
    "header header header header"
    "main main main side"
    "footer footer footer side";
}

.header { grid-area: header; }
.main { grid-area: main; }
